import clsx from "clsx";
import { useRef } from "react";
import type {
  ButtonViewModel as ButtonData,
  ContentMetadataViewModel as ContentMetadataData,
  DecoratedAvatarViewModel,
  LockupMetadataViewModel,
} from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import type { AttributedText } from "../../model/text";
import { useImpression } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { AttributedString } from "../text/AttributedString";
import { EndpointLink } from "../text/EndpointLink";
import { ButtonViewModel } from "../button/ButtonViewModel";
import { AvatarShape, type AvatarSize } from "../avatar/AvatarShape";
import { ContentMetadata } from "./ContentMetadata";
import { useLockup } from "./lockupContext";
import styles from "./LockupMetadata.module.css";

const AVATAR_SIZES: Record<string, AvatarSize> = {
  AVATAR_SIZE_XXS: "xs",
  AVATAR_SIZE_XS: "xs",
  AVATAR_SIZE_S: "s",
  AVATAR_SIZE_M: "m",
  AVATAR_SIZE_40: "l",
  AVATAR_SIZE_L: "l",
  AVATAR_SIZE_XL: "xl",
  AVATAR_SIZE_XXL: "xxl",
  AVATAR_SIZE_XXXL: "xxxl",
};

/**
 * A channel avatar with its decorations (live ring), linking to the
 * channel. `size` (an AVATAR_SIZE_* value) overrides the data's size.
 */
export function DecoratedAvatar({ data, size }: { data: DecoratedAvatarViewModel; size?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const avatar = data.avatar.avatarViewModel;
  const sources = (avatar.image as { sources?: Array<{ url: string; width?: number; height?: number }> }).sources;
  const command = data.rendererContext?.commandContext?.onTap?.innertubeCommand as Endpoint | undefined;
  const label = data.a11yLabel ?? data.rendererContext?.accessibilityContext?.label;
  return (
    <div ref={ref} className={styles.decoratedAvatar}>
      <AvatarShape
        sources={sources}
        size={AVATAR_SIZES[size ?? avatar.avatarImageSize ?? ""] ?? "m"}
        label={label}
        onClick={command ? () => runCommand(command) : undefined}
        className={data.liveData ? styles.live : undefined}
      />
      {data.liveData && <div className={styles.liveBadge}>{data.liveData.liveBadgeText}</div>}
    </div>
  );
}

/** The text side of a content lockup: avatar, title, metadata rows and menu. */
export function LockupMetadata({ data }: { data: LockupMetadataViewModel }) {
  const { command, compact } = useLockup();
  const title = data.title.content;
  const menu = data.menuButton?.buttonViewModel as ButtonData | undefined;
  const avatar = compact ? undefined : data.image?.decoratedAvatarViewModel;
  return (
    <div className={clsx(styles.host, compact && styles.compact)}>
      {avatar && (
        <div className={styles.avatar}>
          <DecoratedAvatar data={avatar} />
        </div>
      )}
      <div className={styles.textContainer}>
        <h3 className={styles.heading} title={title}>
          <EndpointLink endpoint={command} className={styles.title}>
            <AttributedString text={data.title as AttributedText} />
          </EndpointLink>
        </h3>
        <div className={styles.metadata}>
          <ContentMetadata data={data.metadata.contentMetadataViewModel as ContentMetadataData} />
        </div>
      </div>
      {menu && (
        <div className={styles.menuButton}>
          <ButtonViewModel data={menu} />
        </div>
      )}
    </div>
  );
}
