import clsx from "clsx";
import type { VideoSummaryContentViewModel } from "../../model/innertube.gen";
import { unwrap } from "../../model/unwrap";
import { AttributedString } from "../text/AttributedString";
import { DislikeButtonViewModel, LikeButtonViewModel } from "../button/ToggleButtonViewModel";
import styles from "./VideoSummaryContent.module.css";

/** An AI summary of a video, with like and dislike feedback buttons. */
export function VideoSummaryContent({ data, isSearch }: { data: VideoSummaryContentViewModel; isSearch?: boolean }) {
  return (
    <div className={clsx(styles.host, isSearch && styles.search)}>
      <div className={styles.paragraphs}>
        {data.paragraphs.map((p, i) => {
          const paragraph = unwrap<{ text?: { content?: string } }>(p, "videoSummaryParagraphViewModel");
          return (
            <p key={i} className={styles.paragraph}>
              <AttributedString text={paragraph?.text} />
            </p>
          );
        })}
      </div>
      <div className={styles.buttons}>
        {data.likeButtonViewModel && (
          <div className={styles.likeButton}>
            <LikeButtonViewModel data={data.likeButtonViewModel} />
          </div>
        )}
        {data.dislikeButtonViewModel && <DislikeButtonViewModel data={data.dislikeButtonViewModel} />}
      </div>
    </div>
  );
}
