import clsx from "clsx";
import { useRef } from "react";
import type {
  AdAvatarViewModel,
  AdBadgeViewModel,
  AdButtonGroupViewModel,
  AdButtonHoverOverlayViewModel,
  AdButtonViewModel,
  AdDetailsLineViewModel,
  AdImageViewModel,
  ButtonViewModel as ButtonData,
  FeedAdMetadataViewModel,
} from "../../model/innertube.gen";
import { endpointHref, type Endpoint } from "../../model/endpoints";
import { unwrap } from "../../model/unwrap";
import type { AttributedText } from "../../model/text";
import { useImpression } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { AttributedString } from "../text/AttributedString";
import { EndpointLink } from "../text/EndpointLink";
import { Image } from "../image/Image";
import { Icon } from "../icon/Icon";
import { BadgeShape } from "../badge/BadgeShape";
import { ButtonShape } from "../button/ButtonShape";
import { ButtonViewModel } from "../button/ButtonViewModel";
import { AvatarShape } from "../avatar/AvatarShape";
import { useAdInteraction, type AdInteraction } from "./useAdInteraction";
import styles from "./AdParts.module.css";

interface ImageSource {
  url: string;
  width?: number;
  height?: number;
}

const onTapCommand = (interaction: unknown): Endpoint | undefined =>
  (interaction as { onTap?: { innertubeCommand?: Endpoint } } | undefined)?.onTap?.innertubeCommand;

/** An ad's image, clickable through to the advertiser. */
export function AdImage({ data }: { data: AdImageViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const fit = (data.imageProperties as { contentMode?: string } | undefined)?.contentMode === "CONTENT_MODE_SCALE_ASPECT_FIT" ? "contain" : "cover";
  return (
    <div ref={ref} className={styles.adImage}>
      {/* The headline links to the same page, so keyboards and screen readers skip the image. */}
      <EndpointLink endpoint={onTapCommand(data.interaction)} className={styles.imageContainer} tabIndex={-1} aria-hidden="true">
        <Image image={data.imageSources as ImageSource[]} width={360} fit={fit} style={{ backgroundColor: "transparent" }} />
      </EndpointLink>
    </div>
  );
}

/** An ad's call-to-action button. */
export function AdButton({ data }: { data: AdButtonViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const command = onTapCommand(data.interaction);
  const label = data.label as AttributedText;
  const icon = (data.iconImage as { sources?: Array<{ clientResource?: { imageName?: string } }> } | undefined)?.sources?.[0]?.clientResource?.imageName;
  const url = command?.urlEndpoint?.url ?? (command ? endpointHref(command) ?? undefined : undefined);
  const style = data.style;
  return (
    <div ref={ref} className={styles.adButton} style={{ transitionDuration: "0.3s" }}>
      <ButtonShape
        text={<AttributedString text={label} />}
        icon={icon}
        iconPosition="trailing"
        buttonStyle={style === "AD_BUTTON_STYLE_OVERLAY_TEXT" ? "text" : style === "AD_BUTTON_STYLE_MONO_TONAL" ? "tonal" : "filled"}
        type={style === "AD_BUTTON_STYLE_OVERLAY_TEXT" ? "overlay" : "mono"}
        label={label?.content}
        title={label?.content}
        href={url}
        fullWidth={data.isFullWidth}
        onClick={(e) => {
          if (command && !command.urlEndpoint) {
            e.preventDefault();
            runCommand(command);
          }
        }}
      />
    </div>
  );
}

export function AdButtonHoverOverlay({ data }: { data: AdButtonHoverOverlayViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const button = unwrap<AdButtonViewModel>(data.button, "adButtonViewModel");
  return (
    <div ref={ref} className={styles.hoverOverlay}>
      {button && <AdButton data={button} />}
    </div>
  );
}

export function AdBadge({ data }: { data: AdBadgeViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const text = (data.label as AttributedText)?.content ?? "";
  return (
    <div ref={ref} className={styles.adBadge}>
      <BadgeShape text={text} badgeStyle="ad" />
    </div>
  );
}

export function AdDetailsLine({ data }: { data: AdDetailsLineViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const attributes = (data.attributes as Array<{ text?: AttributedText }>) ?? [];
  return (
    <div ref={ref} className={clsx(styles.detailsLine, data.style === "AD_DETAILS_LINE_STYLE_RESPONSIVE" && styles.responsive)}>
      {attributes.map((a, i) => (
        <AttributedString key={i} text={a.text} className={styles.detailsText} />
      ))}
    </div>
  );
}

export function AdAvatar({ data }: { data: AdAvatarViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const sources = (data.image as { sources?: ImageSource[] } | undefined)?.sources;
  const label = (data.rendererContext as { accessibilityContext?: { label?: string } } | undefined)?.accessibilityContext?.label;
  return (
    <div ref={ref} className={styles.adAvatar}>
      <AvatarShape sources={sources} size={data.size === "AD_AVATAR_SIZE_XS" ? "xs" : "m"} label={label} onClick={() => runCommand(onTapCommand(data.interaction))} />
    </div>
  );
}

/** The text block of an in-feed ad: headline, description, badge, details and menu. */
export function FeedAdMetadata({ data }: { data: FeedAdMetadataViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  useAdInteraction(ref, data.interaction as AdInteraction);
  const search = data.adRenderingContextType === "AD_RENDERING_CONTEXT_TYPE_SEARCH";
  const avatar = unwrap<AdAvatarViewModel>(data.adAvatar, "adAvatarViewModel");
  const badge = unwrap<AdBadgeViewModel>(data.adBadge, "adBadgeViewModel");
  const details = unwrap<AdDetailsLineViewModel>(data.adDetailsLine, "adDetailsLineViewModel");
  const menu = unwrap<ButtonData>(data.menu, "buttonViewModel");
  return (
    <div ref={ref} className={styles.feedAdMetadata}>
      <div className={styles.metadata}>
        <AttributedString text={data.headline as AttributedText} className={clsx(styles.headline, search && styles.headlineSearch)} inheritLinkColor as="h3" />
        {data.description && <AttributedString text={data.description as AttributedText} className={styles.description} inheritLinkColor />}
        <div className={styles.badgeLine}>
          {avatar && (
            <div className={styles.avatarSlot}>
              <AdAvatar data={avatar} />
            </div>
          )}
          {badge && <AdBadge data={badge} />}
          {details && <AdDetailsLine data={details} />}
        </div>
      </div>
      {menu && (
        <div className={styles.menuButton}>
          <ButtonViewModel data={menu} />
        </div>
      )}
    </div>
  );
}

/** A compact ad with a landscape image and no call-to-action button. */
export function CompactLandscapeNoButtonLayout({ data }: { data: { interaction?: unknown; thumbnailImage?: unknown; feedAdMetadata?: unknown; adButtonHoverOverlay?: unknown } }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  useAdInteraction(ref, data.interaction as AdInteraction);
  const image = unwrap<AdImageViewModel>(data.thumbnailImage, "adImageViewModel");
  const metadata = unwrap<FeedAdMetadataViewModel>(data.feedAdMetadata, "feedAdMetadataViewModel");
  const overlay = unwrap<AdButtonHoverOverlayViewModel>(data.adButtonHoverOverlay, "adButtonHoverOverlayViewModel");
  const overlayIcon = (image?.imageProperties as { overlayIcon?: { iconImage?: { sources?: Array<{ clientResource?: { imageName?: string } }> } } } | undefined)?.overlayIcon?.iconImage?.sources?.[0]?.clientResource?.imageName;
  return (
    <div ref={ref} className={styles.compactLandscape} data-renderer="compactLandscapeNoButtonLayoutViewModel">
      <div className={styles.imageHoverContainer} style={{ width: "50%", maxWidth: 500 }}>
        <div className={styles.landscapeImage}>{image && <AdImage data={image} />}</div>
        {overlayIcon && (
          <div className={styles.overlayIcon}>
            <Icon icon={overlayIcon} />
          </div>
        )}
        {overlay && (
          <div className={styles.hoverButton}>
            <AdButtonHoverOverlay data={overlay} />
          </div>
        )}
      </div>
      <div className={styles.compactMetadata}>{metadata && <FeedAdMetadata data={metadata} />}</div>
    </div>
  );
}

/** The two call-to-action buttons under a video ad. */
export function AdButtonGroup({ data }: { data: AdButtonGroupViewModel }) {
  const primary = unwrap<AdButtonViewModel>(data.primaryAdButton, "adButtonViewModel");
  const secondary = unwrap<AdButtonViewModel>(data.secondaryAdButton, "adButtonViewModel");
  return (
    <div className={clsx(styles.buttonGroup, styles.compactWidth)}>
      {secondary && (
        <div className={styles.secondary}>
          <AdButton data={secondary} />
        </div>
      )}
      {primary && (
        <div className={styles.primary}>
          <AdButton data={primary} />
        </div>
      )}
    </div>
  );
}
