import clsx from "clsx";
import { useIsFetching } from "@tanstack/react-query";
import { useUiStore } from "../../state/ui";
import { Masthead } from "../masthead/Masthead";
import { Guide } from "../guide/Guide";
import { useGuideMode } from "../guide/useGuideMode";
import { PageStack } from "./PageStack";
import { PopupContainer } from "./PopupContainer";
import styles from "./AppLayout.module.css";

function NavigationProgress() {
  const active = useIsFetching() > 0;
  return (
    <div className={clsx(styles.progress, active && styles.progressActive)} aria-hidden="true">
      <div className={styles.progressBar} />
    </div>
  );
}

/** The app shell: masthead, guide and the current page. */
export function AppLayout() {
  const guideOpen = useUiStore((s) => s.guideOpen);
  const guideMode = useGuideMode();
  return (
    <div className={clsx(styles.app, guideMode === "drawer" ? styles.guideDrawer : guideOpen && styles.guideOpen)}>
      <div className={styles.content}>
        <Masthead />
        <Guide />
        <main className={styles.pages}>
          <PageStack />
        </main>
      </div>
      <PopupContainer />
      <NavigationProgress />
    </div>
  );
}
