import clsx from "clsx";
import { useRef } from "react";
import { useIntl } from "react-intl";
import type { ShortsLockupViewModel } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import type { AttributedText } from "../../model/text";
import { unwrap } from "../../model/unwrap";
import { useImpression } from "../../logging/impressions";
import { useRunCommand } from "../../commands/useRunCommand";
import { EndpointLink } from "../text/EndpointLink";
import { AttributedString } from "../text/AttributedString";
import { ThumbnailViewModel } from "../thumbnail/ThumbnailViewModel";
import { ButtonShape } from "../button/ButtonShape";
import { BadgeShape } from "../badge/BadgeShape";
import styles from "./ShortsLockup.module.css";

interface Overlay {
  primaryText?: AttributedText;
  secondaryText?: AttributedText;
}

/** A Shorts lockup: a portrait thumbnail with the title and views below it. */
export function ShortsLockup({ data, className }: { data: ShortsLockupViewModel; className?: string }) {
  const intl = useIntl();
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const runCommand = useRunCommand();
  const endpoint = data.onTap?.innertubeCommand as Endpoint | undefined;
  const metadata = (data.overlayMetadata ?? {}) as Overlay;
  const title = metadata.primaryText?.content ?? "";
  const badge = unwrap<{ badgeText?: string; accessibilityLabel?: string }>(data.badge, "badgeViewModel");
  return (
    <div ref={ref} className={clsx(styles.lockup, className)} data-renderer="shortsLockupViewModel">
      <EndpointLink endpoint={endpoint} className={styles.endpoint} tabIndex={-1} aria-hidden="true">
        <div className={styles.thumbnailContainer}>
          <ThumbnailViewModel data={data.thumbnailViewModel} aspectRatio="2:3" width={210} />
          {badge?.badgeText && (
            <div className={styles.badge}>
              <BadgeShape text={badge.badgeText} label={badge.accessibilityLabel} badgeStyle="overlayWhite" />
            </div>
          )}
        </div>
      </EndpointLink>
      <div className={styles.outsideMetadata}>
        <div className={styles.text}>
          <h3 className={styles.title}>
            <EndpointLink endpoint={endpoint} className={styles.titleLink} title={title} aria-label={data.accessibilityText}>
              <AttributedString text={metadata.primaryText} />
            </EndpointLink>
          </h3>
          <div className={styles.subhead}>
            <AttributedString text={metadata.secondaryText} />
          </div>
        </div>
        <div className={styles.menu}>
          <ButtonShape
            icon="MORE_VERT"
            label={data.menuOnTapA11yLabel || intl.formatMessage({ id: "shorts.menu", defaultMessage: "More actions" })}
            title={data.menuOnTapA11yLabel}
            onClick={() => runCommand(data.menuOnTap?.innertubeCommand as Endpoint | undefined)}
          />
        </div>
      </div>
    </div>
  );
}
