import clsx from "clsx";
import { useRef, useState } from "react";
import type { HorizontalCardListRenderer } from "../../model/innertube.gen";
import { useImpression } from "../../logging/impressions";
import { useResizeObserver } from "../../hooks/useResizeObserver";
import { ButtonRenderer } from "../button/ButtonRenderer";
import { RendererList } from "../../renderers/Renderer";
import styles from "./HorizontalCardList.module.css";

const CARD_WIDTH = 186;
const GAP = 8;

/**
 * A horizontally scrolling row of cards. Cards are sized to fill the row;
 * the first seven, or one more than fit, are rendered up front and the rest
 * when the user scrolls.
 */
export function HorizontalCardList({ data }: { data: HorizontalCardListRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  const scrollerRef = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const cards = data.cards ?? [];
  const [itemWidth, setItemWidth] = useState(CARD_WIDTH);
  const [shown, setShown] = useState(Math.min(cards.length, 7));
  const [overflowing, setOverflowing] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const measure = () => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    const width = scroller.clientWidth;
    const perRow = Math.max(1, Math.floor(width / CARD_WIDTH));
    setItemWidth(width ? Math.floor((width - GAP * (perRow - 1)) / perRow) : CARD_WIDTH);
    setShown((n) => Math.max(n, Math.min(cards.length, Math.max(7, perRow + 1))));
    setOverflowing(scroller.scrollWidth > width);
  };
  useResizeObserver(scrollerRef, measure);
  const scrollBy = (direction: 1 | -1) => {
    const scroller = scrollerRef.current;
    if (!scroller) return;
    setShown(cards.length);
    scroller.scrollBy({ left: direction * scroller.clientWidth, behavior: "smooth" });
  };
  return (
    <div
      ref={ref}
      className={clsx(styles.list, overflowing && styles.overflowing)}
      style={{ "--yt-card-width": `${itemWidth}px` } as React.CSSProperties}
    >
      <div ref={scrollerRef} className={styles.scroller} onScroll={(e) => setScrolled(e.currentTarget.scrollLeft > 0)}>
        <div className={styles.items}>
          <RendererList items={cards.slice(0, shown)} />
        </div>
      </div>
      {scrolled && data.previousButton && (
        <div className={styles.leftArrow}>
          <ButtonRenderer data={data.previousButton.buttonRenderer} onClick={() => scrollBy(-1)} />
        </div>
      )}
      {overflowing && data.nextButton && (
        <div className={styles.rightArrow}>
          <ButtonRenderer data={data.nextButton.buttonRenderer} onClick={() => scrollBy(1)} />
        </div>
      )}
    </div>
  );
}
