import clsx from "clsx";
import { useId, useRef, useState } from "react";
import { Link } from "react-router";
import { defineMessages, useIntl } from "react-intl";
import { useUiStore } from "../../state/ui";
import { useGuideMode } from "../guide/useGuideMode";
import { useResizeObserver } from "../../hooks/useResizeObserver";
import { IconButton } from "../../components/button/IconButton";
import { ButtonShape } from "../../components/button/ButtonShape";
import { Tooltip } from "../../components/feedback/Tooltip";
import { Icon } from "../../components/icon/Icon";
import { Searchbox } from "./Searchbox";
import styles from "./Masthead.module.css";

const messages = defineMessages({
  guide: { id: "masthead.guide", defaultMessage: "Guide" },
  home: { id: "masthead.home", defaultMessage: "Home" },
  voice: { id: "masthead.voice", defaultMessage: "Search with your voice" },
  create: { id: "masthead.create", defaultMessage: "Create" },
  notifications: { id: "masthead.notifications", defaultMessage: "Notifications" },
  signIn: { id: "masthead.signIn", defaultMessage: "Sign in" },
});

/** The bar at the top: guide button, logo, searchbox and account buttons. */
export function Masthead() {
  const intl = useIntl();
  const ref = useRef<HTMLElement>(null);
  const guideMode = useGuideMode();
  const toggleGuide = useUiStore((s) => (guideMode === "drawer" ? s.toggleDrawer : s.toggleGuide));
  const [narrow, setNarrow] = useState(false);
  const guideTooltipId = useId();
  const voiceTooltipId = useId();
  useResizeObserver(ref, () => setNarrow((ref.current?.offsetWidth ?? 0) < 656));
  return (
    <div className={styles.mastheadContainer}>
      <header ref={ref} className={clsx(styles.masthead, narrow && styles.narrow)}>
        <div className={styles.background} />
        <div className={styles.container}>
          <div className={styles.start}>
            <IconButton icon="MENU" label={intl.formatMessage(messages.guide)} describedBy={guideTooltipId} onClick={toggleGuide} />
            <div className={styles.logo}>
              <Link to="/" className={styles.logoLink} title={intl.formatMessage(messages.home)}>
                <div className={styles.logoContainer}>
                  <span className={styles.countryCode} />
                  <Icon icon="YOUTUBE_LOGO" size={90} className={styles.logoIcon} />
                </div>
              </Link>
            </div>
          </div>
          <div className={styles.center}>
            <div className={styles.searchboxHost}>
              <Searchbox />
            </div>
            <div className={styles.voiceSearch}>
              <ButtonShape icon="MICROPHONE_ON" label={intl.formatMessage(messages.voice)} describedBy={voiceTooltipId} />
              <Tooltip text={intl.formatMessage(messages.voice)} id={voiceTooltipId} />
            </div>
          </div>
          <div className={styles.end}>
            <div className={styles.buttons}>
              <div className={styles.button}>
                <ButtonShape icon="VIDEO_CALL" text={intl.formatMessage(messages.create)} buttonStyle="tonal" label={intl.formatMessage(messages.create)} title={intl.formatMessage(messages.create)} />
              </div>
              <IconButton icon="NOTIFICATIONS" label={intl.formatMessage(messages.notifications)} />
              <div className={styles.button}>
                <ButtonShape
                  icon="AVATAR_LOGGED_OUT"
                  text={intl.formatMessage(messages.signIn)}
                  buttonStyle="outline"
                  type="suggestive"
                  label={intl.formatMessage(messages.signIn)}
                  title={intl.formatMessage(messages.signIn)}
                />
              </div>
            </div>
          </div>
        </div>
        <Tooltip text={intl.formatMessage(messages.guide)} id={guideTooltipId} className={styles.guideTooltip} />
      </header>
    </div>
  );
}
