import clsx from "clsx";
import { useState, type FormEvent } from "react";
import { useNavigate, useSearchParams } from "react-router";
import { defineMessages, useIntl } from "react-intl";
import { Icon } from "../../components/icon/Icon";
import { TouchFeedback } from "../../components/feedback/TouchFeedback";
import styles from "./Searchbox.module.css";

const messages = defineMessages({
  placeholder: { id: "searchbox.placeholder", defaultMessage: "Search" },
  search: { id: "searchbox.search", defaultMessage: "Search" },
  clear: { id: "searchbox.clear", defaultMessage: "Clear search query" },
});

/** The masthead's search field. Submitting it opens the results page. */
export function Searchbox() {
  const intl = useIntl();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const urlQuery = params.get("search_query");
  const [query, setQuery] = useState(urlQuery ?? "");
  // Follow the URL on Back, Forward and links to other queries. Pages without
  // a query, such as the watch page, keep the last one in the box.
  const [lastUrlQuery, setLastUrlQuery] = useState(urlQuery);
  if (urlQuery !== lastUrlQuery) {
    setLastUrlQuery(urlQuery);
    if (urlQuery !== null) setQuery(urlQuery);
  }
  const [focused, setFocused] = useState(false);
  const submit = (e: FormEvent) => {
    e.preventDefault();
    const q = query.trim();
    if (q) navigate(`/results?search_query=${encodeURIComponent(q)}`);
  };
  return (
    <div className={clsx(styles.searchbox, focused && styles.focused)}>
      <form className={styles.form} role="search" onSubmit={submit}>
        <div className={styles.inputBox}>
          <input
            className={styles.input}
            type="text"
            aria-label={intl.formatMessage(messages.search)}
            name="search_query"
            autoComplete="off"
            placeholder={intl.formatMessage(messages.placeholder)}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
          />
          <div className={styles.clearContainer}>
            <button type="button" className={styles.clear} aria-label={intl.formatMessage(messages.clear)} hidden={!query} onClick={() => setQuery("")}>
              <Icon icon="CLOSE" />
              <TouchFeedback />
            </button>
          </div>
        </div>
        <button type="submit" className={styles.searchButton} aria-label={intl.formatMessage(messages.search)} title={intl.formatMessage(messages.search)}>
          <Icon icon="SEARCH" />
          <TouchFeedback />
        </button>
      </form>
    </div>
  );
}
