import { createBrowserRouter } from "react-router";
import { AppLayout } from "./features/shell/AppLayout";
import { RouteError } from "./features/shell/ErrorBoundary";
import { track } from "./workload/idle";

function Home() {
  return null;
}

/**
 * The app is served from a directory, so the router's base is the
 * directory of the page it was loaded from.
 */
function basename(): string {
  return location.pathname.replace(/\/[^/]*$/, "") || "/";
}

export function createAppRouter() {
  return createBrowserRouter(
    [
      {
        path: "/",
        Component: AppLayout,
        ErrorBoundary: RouteError,
        children: [
          { index: true, Component: Home },
          { path: "index.html", Component: Home },
          {
            path: "results",
            ErrorBoundary: RouteError,
            lazy: { Component: async () => (await track(import("./features/search/SearchPage"))).default },
          },
          {
            path: "watch",
            ErrorBoundary: RouteError,
            lazy: { Component: async () => (await track(import("./features/watch/WatchPage"))).default },
          },
          ...["channel/:channelId/:tab?", ":handle/:tab?"].map((path) => ({
            path,
            ErrorBoundary: RouteError,
            lazy: { Component: async () => (await track(import("./features/channel/ChannelPage"))).default },
          })),
          { path: "*", Component: Home },
        ],
      },
    ],
    { basename: basename() },
  );
}
