import { createContext, use, useEffect, useRef } from "react";
import type {
  AdSlotRenderer,
  InFeedAdLayoutRenderer,
  LockupViewModel as LockupViewModelData,
  SearchPyvRenderer,
  VideoDisplayCompactButtonGroupLayoutViewModel,
} from "../../model/innertube.gen";
import { unwrap } from "../../model/unwrap";
import { adLayoutEntered, adLayoutExited, adSlotEntered, adSlotExited, type AdLayoutMetadata, type AdSlotMetadata } from "../../logging/ads";
import { useImpression } from "../../logging/impressions";
import { Renderer } from "../../renderers/Renderer";
import { LockupViewModel } from "../lockup/LockupViewModel";
import { useAdInteraction, type AdInteraction } from "./useAdInteraction";
import styles from "./AdSlot.module.css";

const AdSlotContext = createContext<AdSlotMetadata | undefined>(undefined);

/** An ad slot in a feed. Its lifetime is reported to the ads control flow. */
export function AdSlot({ data }: { data: AdSlotRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const slot = data.adSlotMetadata as AdSlotMetadata;
  useEffect(() => {
    adSlotEntered(slot);
    return () => adSlotExited(slot);
  }, [slot]);
  return (
    <div ref={ref} className={styles.slot} data-renderer="adSlotRenderer">
      <div className={styles.fulfilled}>
        <AdSlotContext value={slot}>
          <Renderer data={data.fulfillmentContent?.fulfilledLayout} />
        </AdSlotContext>
      </div>
    </div>
  );
}

const LAYOUT_CLASSES: Record<string, string> = {
  LAYOUT_TYPE_DISPLAY_COMPACT_LANDSCAPE_NO_BUTTON: styles.compactLandscape,
  LAYOUT_TYPE_VIDEO_DISPLAY_COMPACT_BUTTON_GROUP: styles.videoDisplay,
};

/** The layout that fills an in-feed ad slot. */
export function InFeedAdLayout({ data }: { data: InFeedAdLayoutRenderer }) {
  const slot = use(AdSlotContext);
  const layout = data.adLayoutMetadata as AdLayoutMetadata;
  useEffect(() => {
    adLayoutEntered(slot, layout);
    return () => adLayoutExited(slot, layout);
  }, [slot, layout]);
  return (
    <div className={styles.layout}>
      <div className={LAYOUT_CLASSES[layout.layoutType ?? ""] ?? styles.adLayout}>
        <Renderer data={data.renderingContent} />
      </div>
    </div>
  );
}

/** Promoted videos in search results: a list of ad slots. */
export function SearchPyv({ data }: { data: SearchPyvRenderer }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  return (
    <div ref={ref} className={styles.pyv} data-renderer="searchPyvRenderer">
      <div className={styles.contents}>
        {data.ads.map((ad, i) => (
          <Renderer key={i} data={ad} />
        ))}
      </div>
    </div>
  );
}

/** A video ad: a lockup with the ad's metadata and call-to-action buttons. */
export function VideoDisplayCompactButtonGroupLayout({ data }: { data: VideoDisplayCompactButtonGroupLayoutViewModel }) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  useAdInteraction(ref, data.interaction as AdInteraction);
  const lockup = unwrap<LockupViewModelData>(data.videoLockup, "lockupViewModel");
  return (
    <div ref={ref} className={styles.videoDisplayLayout} data-renderer="videoDisplayCompactButtonGroupLayoutViewModel">
      {lockup && <LockupViewModel data={lockup} />}
    </div>
  );
}
