import { createContext, use } from "react";
import type { Endpoint } from "../../model/endpoints";

export interface LockupContextValue {
  /** The lockup's command: its title links there. */
  command?: Endpoint;
  /** The compact style of the watch page's related list. */
  compact?: boolean;
}

/** The lockup that a metadata block belongs to. */
export const LockupContext = createContext<LockupContextValue>({});

export function useLockup(): LockupContextValue {
  return use(LockupContext);
}
