import clsx from "clsx";
import { Image } from "../image/Image";
import type { ThumbnailImage } from "../image/thumbnails";
import styles from "./AvatarShape.module.css";

export type AvatarSize = "xs" | "s" | "m" | "l" | "xl" | "xxl" | "xxxl";

const PIXELS: Record<AvatarSize, number> = { xs: 24, s: 32, m: 36, l: 40, xl: 72, xxl: 120, xxxl: 160 };

export interface AvatarShapeProps {
  sources: ThumbnailImage[] | undefined;
  size?: AvatarSize;
  label?: string;
  onClick?: () => void;
  className?: string;
}

/** A round avatar image, a button when it has an action. */
export function AvatarShape({ sources, size = "m", label, onClick, className }: AvatarShapeProps) {
  const image = (
    <span className={styles.frame}>
      <span className={styles[size]}>
        <Image image={sources} width={PIXELS[size]} />
      </span>
    </span>
  );
  if (onClick) {
    return (
      <button type="button" className={clsx(styles.avatar, styles.tappable, className)} aria-label={label} onClick={onClick}>
        {image}
      </button>
    );
  }
  return (
    <div className={clsx(styles.avatar, className)} role={label ? "img" : undefined} aria-label={label}>
      {image}
    </div>
  );
}
