import { Activity, useState, type ReactNode } from "react";
import { useLocation, useOutlet } from "react-router";
import { isChannelPath } from "../../model/endpoints";

const PAGE_TYPES = ["search", "watch", "channel"] as const;
type PageType = (typeof PAGE_TYPES)[number];

function pageTypeOf(pathname: string): PageType | null {
  if (pathname === "/results") return "search";
  if (pathname === "/watch") return "watch";
  if (isChannelPath(pathname)) return "channel";
  return null;
}

interface KeptPage {
  locationKey: string;
  element: ReactNode;
}

/**
 * The pages. The last page of each type stays mounted, hidden in an
 * <Activity>, while a page of another type is shown, as YouTube keeps the
 * previous page in the document: going back to it shows it as it was.
 * Pages of the same type replace each other.
 */
export function PageStack() {
  const location = useLocation();
  const outlet = useOutlet();
  const current = pageTypeOf(location.pathname);
  const [kept, setKept] = useState<Partial<Record<PageType, KeptPage>>>({});
  if (current && kept[current]?.locationKey !== location.key) {
    setKept({ ...kept, [current]: { locationKey: location.key, element: outlet } });
  }
  if (!current) return outlet;
  return PAGE_TYPES.map((type) => {
    const element = type === current ? outlet : kept[type]?.element;
    if (!element) return null;
    return (
      <Activity key={type} mode={type === current ? "visible" : "hidden"}>
        {element}
      </Activity>
    );
  });
}
