import { useEffect, type RefObject } from "react";
import { flattenCommand, type Endpoint } from "../../model/endpoints";

// Ad pings: an ad's first-visible commands and its active-view (viewable)
// commands are sent as pings, not as logging events. The simulated server
// has no ping endpoint, so the commands are resolved but not sent.

export interface AdInteraction {
  onFirstVisible?: { performOnceCommand?: { identifier?: string; command?: Endpoint } } & Endpoint;
}

const sentOnce = new Set<string>();

function ping(command: Endpoint | undefined) {
  flattenCommand(command);
}

let observer: IntersectionObserver | null = null;
const onVisible = new WeakMap<Element, () => void>();

function visibilityObserver(): IntersectionObserver {
  observer ??= new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        observer!.unobserve(entry.target);
        onVisible.get(entry.target)?.();
        onVisible.delete(entry.target);
      }
    },
    { threshold: 0.5 },
  );
  return observer;
}

/** Sends an ad component's first-visible ping once it is half visible. */
export function useAdInteraction(ref: RefObject<Element | null>, interaction: AdInteraction | undefined): void {
  const first = interaction?.onFirstVisible;
  useEffect(() => {
    const el = ref.current;
    if (!el || !first) return;
    const obs = visibilityObserver();
    onVisible.set(el, () => {
      const once = first.performOnceCommand;
      if (once?.identifier) {
        if (sentOnce.has(once.identifier)) return;
        sentOnce.add(once.identifier);
        ping(once.command);
      } else ping(first);
    });
    obs.observe(el);
    return () => {
      obs.unobserve(el);
      onVisible.delete(el);
    };
  }, [ref, first]);
}
