import clsx from "clsx";
import { Fragment } from "react";
import type { ContentMetadataViewModel as ContentMetadataData } from "../../model/innertube.gen";
import type { AttributedText } from "../../model/text";
import { AttributedString } from "../text/AttributedString";
import { Icon } from "../icon/Icon";
import styles from "./ContentMetadata.module.css";

type Row = ContentMetadataData["metadataRows"][number];
type Part = NonNullable<Row["metadataParts"]>[number];

function MetadataPart({ part }: { part: Part }) {
  const leading = part.leadingIcon;
  const trailing = part.icon;
  return (
    <>
      {leading && <Icon icon={leading.name} size={leading.height || 12} className={styles.icon} />}
      <AttributedString text={part.text as AttributedText} className={clsx(styles.text, part.enableTruncation && styles.truncate)} />
      {trailing && <Icon icon={trailing.name} size={trailing.height || 12} label={trailing.accessibilityLabel} className={styles.icon} />}
    </>
  );
}

/** One row of metadata parts, between delimiters. */
function MetadataRow({ row, delimiter }: { row: Row; delimiter: string }) {
  return (
    <div className={styles.row}>
      {row.metadataParts?.map((part, i) => (
        <span key={i} className={styles.part} aria-label={part.accessibilityLabel}>
          {i > 0 && (
            <span className={styles.delimiter} aria-hidden="true">
              {delimiter}
            </span>
          )}
          <MetadataPart part={part} />
        </span>
      ))}
    </div>
  );
}

/**
 * Rows of content metadata, such as the channel, views and age of a video.
 * Inline rows flow on one line, between delimiters.
 */
export function ContentMetadata({ data, className, inline }: { data: ContentMetadataData; className?: string; inline?: boolean }) {
  const delimiter = (data as { delimiter?: string }).delimiter || "•";
  const rows = data.metadataRows.filter((row) => row.metadataParts?.length);
  return (
    <div className={clsx(styles.host, inline && styles.inline, className)}>
      {rows.map((row, i) => (
        <Fragment key={i}>
          {inline && i > 0 && (
            <span className={styles.delimiter} aria-hidden="true">
              {delimiter}
            </span>
          )}
          <MetadataRow row={row} delimiter={delimiter} />
        </Fragment>
      ))}
    </div>
  );
}
