import clsx from "clsx";
import { NavLink } from "react-router";
import { defineMessages, useIntl, type MessageDescriptor } from "react-intl";
import { useUiStore } from "../../state/ui";
import { useGuideMode } from "./useGuideMode";
import { Icon } from "../../components/icon/Icon";
import { TouchFeedback } from "../../components/feedback/TouchFeedback";
import styles from "./Guide.module.css";

const footer = defineMessages<{ rights: { year: number } }>({
  rights: { id: "guide.footer.rights", defaultMessage: "© {year} Example" },
});

const m = defineMessages({
  home: { id: "guide.home", defaultMessage: "Home" },
  shorts: { id: "guide.shorts", defaultMessage: "Shorts" },
  subscriptions: { id: "guide.subscriptions", defaultMessage: "Subscriptions" },
  you: { id: "guide.you", defaultMessage: "You" },
  history: { id: "guide.history", defaultMessage: "History" },
  playlists: { id: "guide.playlists", defaultMessage: "Playlists" },
  watchLater: { id: "guide.watchLater", defaultMessage: "Watch later" },
  liked: { id: "guide.liked", defaultMessage: "Liked videos" },
  explore: { id: "guide.explore", defaultMessage: "Explore" },
  trending: { id: "guide.trending", defaultMessage: "Trending" },
  music: { id: "guide.music", defaultMessage: "Music" },
  gaming: { id: "guide.gaming", defaultMessage: "Gaming" },
  news: { id: "guide.news", defaultMessage: "News" },
  sports: { id: "guide.sports", defaultMessage: "Sports" },
  learning: { id: "guide.learning", defaultMessage: "Learning" },
  podcasts: { id: "guide.podcasts", defaultMessage: "Podcasts" },
  more: { id: "guide.more", defaultMessage: "More from YouTube" },
  about: { id: "guide.footer.about", defaultMessage: "About" },
  press: { id: "guide.footer.press", defaultMessage: "Press" },
  copyright: { id: "guide.footer.copyright", defaultMessage: "Copyright" },
  contact: { id: "guide.footer.contact", defaultMessage: "Contact us" },
  creators: { id: "guide.footer.creators", defaultMessage: "Creators" },
  advertise: { id: "guide.footer.advertise", defaultMessage: "Advertise" },
  developers: { id: "guide.footer.developers", defaultMessage: "Developers" },
  terms: { id: "guide.footer.terms", defaultMessage: "Terms" },
  privacy: { id: "guide.footer.privacy", defaultMessage: "Privacy" },
  policy: { id: "guide.footer.policy", defaultMessage: "Policy & Safety" },
  label: { id: "guide.label", defaultMessage: "Main navigation" },
});

interface Entry {
  title: MessageDescriptor;
  icon: string;
  to: string;
}

interface Section {
  title?: MessageDescriptor;
  entries: Entry[];
}

const SECTIONS: Section[] = [
  {
    entries: [
      { title: m.home, icon: "HOME", to: "/" },
      { title: m.shorts, icon: "SHORTS", to: "/shorts" },
      { title: m.subscriptions, icon: "SUBSCRIPTIONS", to: "/feed/subscriptions" },
    ],
  },
  {
    title: m.you,
    entries: [
      { title: m.history, icon: "HISTORY", to: "/feed/history" },
      { title: m.playlists, icon: "PLAYLISTS", to: "/feed/playlists" },
      { title: m.watchLater, icon: "WATCH_LATER", to: "/playlist?list=WL" },
      { title: m.liked, icon: "LIKED", to: "/playlist?list=LL" },
    ],
  },
  {
    title: m.explore,
    entries: [
      { title: m.trending, icon: "TRENDING", to: "/feed/trending" },
      { title: m.music, icon: "MUSIC", to: "/channel/music" },
      { title: m.gaming, icon: "GAMING", to: "/gaming" },
      { title: m.news, icon: "NEWS", to: "/channel/news" },
      { title: m.sports, icon: "SPORTS", to: "/channel/sports" },
      { title: m.learning, icon: "LEARNING", to: "/channel/learning" },
      { title: m.podcasts, icon: "PODCASTS", to: "/podcasts" },
    ],
  },
  { title: m.more, entries: [] },
];

const FOOTER = [m.about, m.press, m.copyright, m.contact, m.creators, m.advertise, m.developers, m.terms, m.privacy, m.policy];

function GuideEntry({ entry }: { entry: Entry }) {
  const intl = useIntl();
  const title = intl.formatMessage(entry.title);
  const closeDrawer = useUiStore((s) => s.closeDrawer);
  return (
    <div className={styles.entry}>
      <NavLink to={entry.to} end onClick={closeDrawer} className={({ isActive }) => clsx(styles.endpoint, isActive && styles.active)} title={title}>
        <div className={styles.item}>
          <Icon icon={entry.icon} className={styles.icon} />
          <span className={styles.title}>{title}</span>
          <span className={styles.count} />
          <div className={styles.badges} />
          <TouchFeedback />
        </div>
      </NavLink>
    </div>
  );
}

/** The navigation drawer: beside the pages, or over them on watch pages. */
export function Guide() {
  const intl = useIntl();
  const mode = useGuideMode();
  const guideOpen = useUiStore((s) => s.guideOpen);
  const drawerOpen = useUiStore((s) => s.drawerOpen);
  const open = mode === "drawer" ? drawerOpen : guideOpen;
  return (
    <div className={clsx(styles.drawer, open && styles.open, mode === "drawer" && styles.overlay)}>
      <div className={styles.contentContainer}>
        <div className={styles.wrapper}>
          <nav className={styles.content} aria-label={intl.formatMessage(m.label)}>
            <div className={styles.sections}>
              {SECTIONS.map((section, i) => (
                <div key={i} className={styles.section}>
                  {section.title && <h3 className={styles.sectionTitle}>{intl.formatMessage(section.title)}</h3>}
                  <div className={styles.items}>
                    {section.entries.map((entry) => (
                      <GuideEntry key={entry.to} entry={entry} />
                    ))}
                  </div>
                </div>
              ))}
            </div>
            <div className={styles.footer}>
              {FOOTER.map((link) => (
                <a key={link.id} className={styles.footerLink} href="#">
                  {intl.formatMessage(link)}
                </a>
              ))}
              <div className={styles.copyright}>{intl.formatMessage(footer.rights, { year: 2026 })}</div>
            </div>
          </nav>
        </div>
      </div>
    </div>
  );
}
