import type { ReactNode } from "react";
import { IntlProvider } from "react-intl";
import messages from "./compiled/en.json";

/** Provides the precompiled English messages and Intl formatters. */
export function IntlRoot({ children }: { children: ReactNode }) {
  return (
    <IntlProvider locale="en-US" defaultLocale="en-US" messages={messages}>
      {children}
    </IntlProvider>
  );
}
