import type { MacroMarkersListItemRenderer } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { getText } from "../../model/text";
import { EndpointLink } from "../text/EndpointLink";
import { ImgShadow } from "../image/Image";
import { ButtonRenderer } from "../button/ButtonRenderer";
import styles from "./MacroMarkersListItem.module.css";

/** A chapter card: thumbnail, title and start time. */
export function MacroMarkersListItem({ data }: { data: MacroMarkersListItemRenderer }) {
  const title = getText(data.title);
  const share = (data.shareButton as { buttonRenderer?: object } | undefined)?.buttonRenderer;
  return (
    <div className={styles.marker}>
      <EndpointLink endpoint={data.onTap as Endpoint} className={styles.endpoint} aria-label={data.timeDescriptionA11yLabel}>
        <div className={styles.thumbnailContainer}>
          <ImgShadow image={data.thumbnail} width={186} className={styles.thumbnail} />
        </div>
        <div className={styles.details}>
          <h4 className={styles.title} title={title}>
            {title}
          </h4>
          <div className={styles.time}>{getText(data.timeDescription)}</div>
        </div>
      </EndpointLink>
      {share && (
        <div className={styles.share}>
          <ButtonRenderer data={share} />
        </div>
      )}
    </div>
  );
}
