import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./styles/tokens.css";
import "./styles/global.css";
import "./renderers/shared";
import { App } from "./App";
import { createAppRouter } from "./routes";
import { loadConfig } from "./config";
import { loadResponses, resetResponses, type ResponseKind } from "./api/network";
import { openLogQueue } from "./logging/client";
import { startHeartbeat } from "./logging/telemetry";
import { trackReactRoot, whenIdle } from "./workload/idle";
import { nextEvent } from "./workload/events";

/** Response files in data/, by kind, in the order the steps request them. */
const MANIFEST: Partial<Record<ResponseKind, string[]>> = {
  "search-init": ["search-init"],
  "search-append": ["search-append-1", "search-append-2"],
  "search-reload": ["search-reload"],
  watch: ["watch-1", "watch-2", "watch-1"],
  "comments-reload": ["comments-reload"],
  "comments-append": ["comments-append-1", "comments-append-2"],
  "related-append": ["related-append"],
  browse: ["channel-home", "channel-videos"],
  "grid-append": ["grid-append-1", "grid-append-2"],
  player: ["channel-player"],
};

declare global {
  interface Window {
    ytrWorkload?: { nextEvent: typeof nextEvent; whenIdle: typeof whenIdle; resetResponses: typeof resetResponses };
  }
}

async function boot() {
  const base = "data";
  await Promise.all([loadConfig(base), loadResponses(base, MANIFEST), openLogQueue()]);
  startHeartbeat();
  const root = createRoot(document.getElementById("root")!);
  trackReactRoot(root);
  root.render(
    <StrictMode>
      <App router={createAppRouter()} />
    </StrictMode>,
  );
  await whenIdle();
  window.ytrWorkload = { nextEvent, whenIdle, resetResponses };
  window.dispatchEvent(new CustomEvent("ytr-ready"));
}

void boot();
