import type { CollectionThumbnailViewModel as CollectionData } from "../../model/innertube.gen";
import { ThumbnailViewModel } from "./ThumbnailViewModel";
import styles from "./CollectionThumbnailViewModel.module.css";

/** The colour of a stack layer: the theme's colour from the data, as ARGB. */
function stackColor(argb: number | undefined): string | undefined {
  if (argb === undefined) return undefined;
  return `rgb(${(argb >> 16) & 255}, ${(argb >> 8) & 255}, ${argb & 255})`;
}

/** A playlist's thumbnail: the first video's thumbnail on a stack of two layers. */
export function CollectionThumbnailViewModel({ data }: { data: CollectionData }) {
  const color = stackColor(data.stackColor?.lightTheme);
  return (
    <div className={styles.collection}>
      <div className={styles.stack}>
        <div className={styles.layer2} style={{ backgroundColor: color }} />
        <div className={styles.layer1} style={{ backgroundColor: color }} />
      </div>
      <ThumbnailViewModel data={data.primaryThumbnail.thumbnailViewModel} width={360} />
    </div>
  );
}
