import clsx from "clsx";
import { useRef } from "react";
import type { LockupViewModel as LockupData } from "../../model/innertube.gen";
import type { Endpoint } from "../../model/endpoints";
import { useImpression } from "../../logging/impressions";
import { TouchFeedback } from "../feedback/TouchFeedback";
import { EndpointLink } from "../text/EndpointLink";
import { ThumbnailViewModel, type ThumbnailViewModelProps } from "../thumbnail/ThumbnailViewModel";
import { Renderer } from "../../renderers/Renderer";
import { LockupContext } from "./lockupContext";
import styles from "./LockupViewModel.module.css";

export interface LockupViewModelProps {
  data: LockupData;
  orientation?: "horizontal" | "vertical";
  /** The width of the thumbnail, as a share of the lockup's. */
  imageWidth?: string;
  /**
   * The compact style of the watch page's related list: no avatar, the menu
   * button at the bottom right and the title clamped to three lines.
   */
  compact?: boolean;
  className?: string;
  /** A class for the outer element, which the lockup's container sizes. */
  wrapperClassName?: string;
}

/**
 * A content lockup: a thumbnail and a metadata block, for a video, playlist
 * or ad. The metadata and attachment renderers come from the data.
 */
export function LockupViewModel({ data, orientation = "horizontal", imageWidth = "50%", compact, className, wrapperClassName }: LockupViewModelProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  const content = data.contentImage as { thumbnailViewModel?: unknown; collectionThumbnailViewModel?: unknown };
  const command = (data.rendererContext as { commandContext?: { onTap?: { innertubeCommand?: Endpoint } } } | undefined)?.commandContext?.onTap?.innertubeCommand;
  return (
    <div className={clsx(styles.wrapper, wrapperClassName)} data-renderer="lockupViewModel">
      <div ref={ref} className={clsx(styles.lockup, styles[orientation], className)} data-content-id={data.contentId}>
        <TouchFeedback className={styles.feedback} />
        <EndpointLink
          endpoint={command}
          className={styles.contentImage}
          style={orientation === "horizontal" ? { width: imageWidth } : undefined}
          tabIndex={-1}
          aria-hidden="true"
        >
          {content?.thumbnailViewModel ? (
            <ThumbnailViewModel data={content.thumbnailViewModel as ThumbnailViewModelProps["data"]} width={360} />
          ) : (
            <Renderer data={content} />
          )}
        </EndpointLink>
        <div className={styles.metadata}>
          <LockupContext value={{ command, compact }}>
            <Renderer data={data.metadata} />
          </LockupContext>
          {data.attachmentSlot && <Renderer data={data.attachmentSlot} />}
        </div>
      </div>
    </div>
  );
}

/** Attachments under a lockup's metadata, such as an ad's buttons. */
export function LockupAttachments({ data }: { data: { attachments?: object[] } }) {
  return (
    <div className={styles.attachments}>
      {data.attachments?.map((attachment, i) => (
        <div key={i} className={styles.attachment}>
          <Renderer data={attachment} />
        </div>
      ))}
    </div>
  );
}
