import { useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { useLocation } from "react-router";
import { useUiStore, type MenuItem, type OpenPopup } from "../../state/ui";
import { useRunCommand } from "../../commands/useRunCommand";
import { logClick } from "../../logging/impressions";
import { getText, type FormattedText } from "../../model/text";
import { Icon } from "../../components/icon/Icon";
import { resolveRenderer } from "../../renderers/registry";
import styles from "./PopupContainer.module.css";

function MenuPopup({ items, anchor, label, onClose }: { items: MenuItem[]; anchor: DOMRect; label?: string; onClose: () => void }) {
  const runCommand = useRunCommand();
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    ref.current?.querySelector<HTMLElement>("[role=menuitem]")?.focus();
  }, []);
  return (
    <div ref={ref} className={styles.menu} role="menu" aria-label={label} style={{ top: anchor.bottom, left: Math.max(8, anchor.right - 240) }}>
      {items.map((item, i) => (
        <div key={i} className={item.hasSeparator ? styles.separated : undefined}>
          <button
            type="button"
            role="menuitem"
            className={styles.item}
            onClick={() => {
              logClick({ trackingParams: item.trackingParams });
              onClose();
              runCommand(item.command);
            }}
          >
            {item.icon && <Icon icon={item.icon} />}
            <span className={styles.itemText}>{item.text}</span>
          </button>
        </div>
      ))}
    </div>
  );
}

function restoreFocus(popup: OpenPopup) {
  if (popup.returnFocus?.isConnected) popup.returnFocus.focus();
}

/** A dialog's name: the title of its renderer, if it has one. */
function dialogLabel(data: unknown): string | undefined {
  return getText((data as { title?: FormattedText } | null)?.title) || undefined;
}

function DialogPopup({ renderer, data }: { renderer: string; data: unknown }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    ref.current?.focus();
  }, []);
  const resolved = resolveRenderer({ [renderer]: data });
  if (!resolved) return null;
  const [, Component] = resolved;
  return (
    <div ref={ref} className={styles.dialog} role="dialog" aria-modal="true" aria-label={dialogLabel(data)} tabIndex={-1}>
      <Component data={data} />
    </div>
  );
}

/**
 * Shows the current popup (menu or dialog) above the page. It closes on
 * Escape, on a click outside it, and when the page changes. Escape and the
 * menu's items return focus to where it was when the popup opened.
 */
export function PopupContainer() {
  const popup = useUiStore((s) => s.popup);
  const closePopup = useUiStore((s) => s.closePopup);
  const { key: locationKey } = useLocation();
  useEffect(() => {
    if (!popup) return;
    const onPointerDown = (e: PointerEvent) => {
      if (!(e.target as Element).closest("[role=menu], [role=dialog]")) closePopup();
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      closePopup();
      restoreFocus(popup);
    };
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [popup, closePopup]);

  // A popup belongs to the page it was opened on.
  useEffect(() => {
    closePopup();
  }, [locationKey, closePopup]);

  if (!popup) return null;
  if (popup.kind === "dialog") return createPortal(<DialogPopup renderer={popup.renderer} data={popup.data} />, document.body);
  const closeMenu = () => {
    closePopup();
    restoreFocus(popup);
  };
  return createPortal(<MenuPopup items={popup.items} anchor={popup.anchor} label={popup.label} onClose={closeMenu} />, document.body);
}
